window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-556e8594370c39dd"]={"versions": [{"id": "FIG-556e8594370c39dd", "releases": ["R2.1.20"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Speicherarchitektur- und Mapping-Diagramm der AUTOSAR-Basessoftware für das Modul EEPROM Abstraction (Ea). Das Schaubild visualisiert die Adressraumtransformation zwischen der logischen, blockorientierten Adressierung im virtuellen Adressraum (NVRAM-Manager/Memory-Abstraction-Interface-Sicht) und der seitenorientierten Belegung im physikalischen Adressraum des zugrunde liegenden EEPROM-Treibers (Eep).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Dargestellt sind zwei vertikale Speichersäulen sowie Adressierungszeiger und Beschreibungsblöcke:</p>\n<ul class=\"fig-list\"><li><strong>Virtual address space</strong> mit definierter Blockgröße bzw. Page Size von 64 KBytes: Unterteilt in 16-Bit-Blocknummern (horizontale Achse/Zeiger) und 16-Bit-Block-Offset (vertikaler Offset innerhalb eines 64-KB-Blocks). Exemplarisch belegt durch drei logische Datenblöcke: Block 1 (grün, 32 Bytes am Blockanfang), Block 2 (blau, 100 Bytes nach ungenutztem Zwischenraum) und Block 3 (gelb, 38 Bytes nach weiterem Zwischenraum). Die ungenutzten Bereiche sind schraffiert.\n</li><li><strong>Physical address space</strong> mit fester Page Size von 8 Bytes: Enthält die lückenlos aufeinanderfolgend abgebildeten Nutzdatenblöcke.\n</li><li><strong>Zuordnungen (Mapping-Pfeile)</strong>: Gestrichelte Projektionslinien verbinden die Blöcke des virtuellen Speichers mit ihren physikalischen Zielen:\n<ul class=\"fig-list\"><li>Block #1 (32 Bytes): belegt 4 Seiten (4 × 8 Bytes), 0 Bytes interner Verschnitt (internal residue).\n</li><li>Block #5 (100 Bytes): belegt 13 Seiten (13 × 8 = 104 Bytes), 4 Bytes interner Verschnitt.\n</li><li>Block #17 (38 Bytes): belegt 5 Seiten (5 × 8 = 40 Bytes), 2 Bytes interner Verschnitt.\n</li></ul>\n</li><li>Fußnote: „Note: Sizes not shown to scale“.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Layout- und Abbildungsdiagramm ohne dynamische Ablauf- oder Nachrichtensequenz. Der Ablauf der Adressumrechnung erfolgt statisch: Ein 32-Bit-Zugriff des NVRAM-Managers setzt sich aus einer 16-Bit-Blocknummer und einem 16-Bit-Offset zusammen. Das EEPROM-Abstraktionsmodul berechnet daraus die lineare physikalische Zieladresse und verteilt die Daten auf ganzzahlige Vielfache der physikalischen 8-Byte-Seiten, wobei bei unvollständigen Endseiten verbleibende Restbytes (Residue) als Padding/Verschnitt ungenutzt bleiben.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ bindend für das Adressierungsschema und Paging des Ea-Moduls:</p>\n<ul class=\"fig-list\"><li>Die virtuelle Adresse besteht aus genau 16 Bit Blocknummer und 16 Bit Offset (Gesamtlänge 32 Bit).\n</li><li>Jeder virtuelle Block besitzt eine Maximalgröße von 64 KByte.\n</li><li>Physikalische Schreib- und Lesezugriffe auf das EEPROM müssen auf die physikalische Page-Größe (hier 8 Bytes) ausgerichtet werden.\n</li><li>Bei Blockgrößen, die kein ganzzahliges Vielfaches der Page Size sind, muss die Modulimplementierung auf die nächste volle Seite aufrunden; der interne Restverschnitt (Residue) darf nicht anderweitig für Nutzdaten belegt werden.\n</li></ul>"}, {"id": "FIG-cbf1fedee81783b9", "releases": ["R3.0.7"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Speicherarchitektur- und Mapping-Diagramm der AUTOSAR-Basessoftware für das Modul EEPROM Abstraction (Ea). Das Schaubild visualisiert die Adressraumtransformation zwischen der logischen, blockorientierten Adressierung im virtuellen Adressraum (NVRAM-Manager/Memory-Abstraction-Interface-Sicht) und der seitenorientierten Belegung im physikalischen Adressraum des zugrunde liegenden EEPROM-Treibers (Eep).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Dargestellt sind zwei vertikale Speichersäulen sowie Adressierungszeiger und Beschreibungsblöcke:</p>\n<ul class=\"fig-list\"><li><strong>Virtual address space</strong> mit definierter Blockgröße bzw. Page Size von 64 KBytes: Unterteilt in 16-Bit-Blocknummern (horizontale Achse/Zeiger) und 16-Bit-Block-Offset (vertikaler Offset innerhalb eines 64-KB-Blocks). Exemplarisch belegt durch drei logische Datenblöcke: Block 1 (grün, 32 Bytes am Blockanfang), Block 2 (blau, 100 Bytes nach ungenutztem Zwischenraum) und Block 3 (gelb, 38 Bytes nach weiterem Zwischenraum). Die ungenutzten Bereiche sind schraffiert.\n</li><li><strong>Physical address space</strong> mit fester Page Size von 8 Bytes: Enthält die lückenlos aufeinanderfolgend abgebildeten Nutzdatenblöcke.\n</li><li><strong>Zuordnungen (Mapping-Pfeile)</strong>: Gestrichelte Projektionslinien verbinden die Blöcke des virtuellen Speichers mit ihren physikalischen Zielen:\n<ul class=\"fig-list\"><li>Block #1 (32 Bytes): belegt 4 Seiten (4 × 8 Bytes), 0 Bytes interner Verschnitt (internal residue).\n</li><li>Block #5 (100 Bytes): belegt 13 Seiten (13 × 8 = 104 Bytes), 4 Bytes interner Verschnitt.\n</li><li>Block #17 (38 Bytes): belegt 5 Seiten (5 × 8 = 40 Bytes), 2 Bytes interner Verschnitt.\n</li></ul>\n</li><li>Fußnote: „Note: Sizes not shown to scale“.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Layout- und Abbildungsdiagramm ohne dynamische Ablauf- oder Nachrichtensequenz. Der Ablauf der Adressumrechnung erfolgt statisch: Ein 32-Bit-Zugriff des NVRAM-Managers setzt sich aus einer 16-Bit-Blocknummer und einem 16-Bit-Offset zusammen. Das EEPROM-Abstraktionsmodul berechnet daraus die lineare physikalische Zieladresse und verteilt die Daten auf ganzzahlige Vielfache der physikalischen 8-Byte-Seiten, wobei bei unvollständigen Endseiten verbleibende Restbytes (Residue) als Padding/Verschnitt ungenutzt bleiben.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ bindend für das Adressierungsschema und Paging des Ea-Moduls:</p>\n<ul class=\"fig-list\"><li>Die virtuelle Adresse besteht aus genau 16 Bit Blocknummer und 16 Bit Offset (Gesamtlänge 32 Bit).\n</li><li>Jeder virtuelle Block besitzt eine Maximalgröße von 64 KByte.\n</li><li>Physikalische Schreib- und Lesezugriffe auf das EEPROM müssen auf die physikalische Page-Größe (hier 8 Bytes) ausgerichtet werden.\n</li><li>Bei Blockgrößen, die kein ganzzahliges Vielfaches der Page Size sind, muss die Modulimplementierung auf die nächste volle Seite aufrunden; der interne Restverschnitt (Residue) darf nicht anderweitig für Nutzdaten belegt werden.\n</li></ul>"}, {"id": "FIG-6f7a5d3a76c9c00d", "releases": ["R3.1.5"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Speicherarchitektur- und Mapping-Diagramm der AUTOSAR-Basessoftware für das Modul EEPROM Abstraction (Ea). Das Schaubild visualisiert die Adressraumtransformation zwischen der logischen, blockorientierten Adressierung im virtuellen Adressraum (NVRAM-Manager/Memory-Abstraction-Interface-Sicht) und der seitenorientierten Belegung im physikalischen Adressraum des zugrunde liegenden EEPROM-Treibers (Eep).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Dargestellt sind zwei vertikale Speichersäulen sowie Adressierungszeiger und Beschreibungsblöcke:</p>\n<ul class=\"fig-list\"><li><strong>Virtual address space</strong> mit definierter Blockgröße bzw. Page Size von 64 KBytes: Unterteilt in 16-Bit-Blocknummern (horizontale Achse/Zeiger) und 16-Bit-Block-Offset (vertikaler Offset innerhalb eines 64-KB-Blocks). Exemplarisch belegt durch drei logische Datenblöcke: Block 1 (grün, 32 Bytes am Blockanfang), Block 2 (blau, 100 Bytes nach ungenutztem Zwischenraum) und Block 3 (gelb, 38 Bytes nach weiterem Zwischenraum). Die ungenutzten Bereiche sind schraffiert.\n</li><li><strong>Physical address space</strong> mit fester Page Size von 8 Bytes: Enthält die lückenlos aufeinanderfolgend abgebildeten Nutzdatenblöcke.\n</li><li><strong>Zuordnungen (Mapping-Pfeile)</strong>: Gestrichelte Projektionslinien verbinden die Blöcke des virtuellen Speichers mit ihren physikalischen Zielen:\n<ul class=\"fig-list\"><li>Block #1 (32 Bytes): belegt 4 Seiten (4 × 8 Bytes), 0 Bytes interner Verschnitt (internal residue).\n</li><li>Block #5 (100 Bytes): belegt 13 Seiten (13 × 8 = 104 Bytes), 4 Bytes interner Verschnitt.\n</li><li>Block #17 (38 Bytes): belegt 5 Seiten (5 × 8 = 40 Bytes), 2 Bytes interner Verschnitt.\n</li></ul>\n</li><li>Fußnote: „Note: Sizes not shown to scale“.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Layout- und Abbildungsdiagramm ohne dynamische Ablauf- oder Nachrichtensequenz. Der Ablauf der Adressumrechnung erfolgt statisch: Ein 32-Bit-Zugriff des NVRAM-Managers setzt sich aus einer 16-Bit-Blocknummer und einem 16-Bit-Offset zusammen. Das EEPROM-Abstraktionsmodul berechnet daraus die lineare physikalische Zieladresse und verteilt die Daten auf ganzzahlige Vielfache der physikalischen 8-Byte-Seiten, wobei bei unvollständigen Endseiten verbleibende Restbytes (Residue) als Padding/Verschnitt ungenutzt bleiben.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ bindend für das Adressierungsschema und Paging des Ea-Moduls:</p>\n<ul class=\"fig-list\"><li>Die virtuelle Adresse besteht aus genau 16 Bit Blocknummer und 16 Bit Offset (Gesamtlänge 32 Bit).\n</li><li>Jeder virtuelle Block besitzt eine Maximalgröße von 64 KByte.\n</li><li>Physikalische Schreib- und Lesezugriffe auf das EEPROM müssen auf die physikalische Page-Größe (hier 8 Bytes) ausgerichtet werden.\n</li><li>Bei Blockgrößen, die kein ganzzahliges Vielfaches der Page Size sind, muss die Modulimplementierung auf die nächste volle Seite aufrunden; der interne Restverschnitt (Residue) darf nicht anderweitig für Nutzdaten belegt werden.\n</li></ul>"}, {"id": "FIG-a2e193515cf12365", "releases": ["R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Speicherarchitektur- und Mapping-Diagramm der AUTOSAR-Basessoftware für das Modul EEPROM Abstraction (Ea). Das Schaubild visualisiert die Adressraumtransformation zwischen der logischen, blockorientierten Adressierung im virtuellen Adressraum (NVRAM-Manager/Memory-Abstraction-Interface-Sicht) und der seitenorientierten Belegung im physikalischen Adressraum des zugrunde liegenden EEPROM-Treibers (Eep).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Dargestellt sind zwei vertikale Speichersäulen sowie Adressierungszeiger und Beschreibungsblöcke:</p>\n<ul class=\"fig-list\"><li><strong>Virtual address space</strong> mit definierter Blockgröße bzw. Page Size von 64 KBytes: Unterteilt in 16-Bit-Blocknummern (horizontale Achse/Zeiger) und 16-Bit-Block-Offset (vertikaler Offset innerhalb eines 64-KB-Blocks). Exemplarisch belegt durch drei logische Datenblöcke: Block 1 (grün, 32 Bytes am Blockanfang), Block 2 (blau, 100 Bytes nach ungenutztem Zwischenraum) und Block 3 (gelb, 38 Bytes nach weiterem Zwischenraum). Die ungenutzten Bereiche sind schraffiert.\n</li><li><strong>Physical address space</strong> mit fester Page Size von 8 Bytes: Enthält die lückenlos aufeinanderfolgend abgebildeten Nutzdatenblöcke.\n</li><li><strong>Zuordnungen (Mapping-Pfeile)</strong>: Gestrichelte Projektionslinien verbinden die Blöcke des virtuellen Speichers mit ihren physikalischen Zielen:\n<ul class=\"fig-list\"><li>Block #1 (32 Bytes): belegt 4 Seiten (4 × 8 Bytes), 0 Bytes interner Verschnitt (internal residue).\n</li><li>Block #5 (100 Bytes): belegt 13 Seiten (13 × 8 = 104 Bytes), 4 Bytes interner Verschnitt.\n</li><li>Block #17 (38 Bytes): belegt 5 Seiten (5 × 8 = 40 Bytes), 2 Bytes interner Verschnitt.\n</li></ul>\n</li><li>Fußnote: „Note: Sizes not shown to scale“.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Layout- und Abbildungsdiagramm ohne dynamische Ablauf- oder Nachrichtensequenz. Der Ablauf der Adressumrechnung erfolgt statisch: Ein 32-Bit-Zugriff des NVRAM-Managers setzt sich aus einer 16-Bit-Blocknummer und einem 16-Bit-Offset zusammen. Das EEPROM-Abstraktionsmodul berechnet daraus die lineare physikalische Zieladresse und verteilt die Daten auf ganzzahlige Vielfache der physikalischen 8-Byte-Seiten, wobei bei unvollständigen Endseiten verbleibende Restbytes (Residue) als Padding/Verschnitt ungenutzt bleiben.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ bindend für das Adressierungsschema und Paging des Ea-Moduls:</p>\n<ul class=\"fig-list\"><li>Die virtuelle Adresse besteht aus genau 16 Bit Blocknummer und 16 Bit Offset (Gesamtlänge 32 Bit).\n</li><li>Jeder virtuelle Block besitzt eine Maximalgröße von 64 KByte.\n</li><li>Physikalische Schreib- und Lesezugriffe auf das EEPROM müssen auf die physikalische Page-Größe (hier 8 Bytes) ausgerichtet werden.\n</li><li>Bei Blockgrößen, die kein ganzzahliges Vielfaches der Page Size sind, muss die Modulimplementierung auf die nächste volle Seite aufrunden; der interne Restverschnitt (Residue) darf nicht anderweitig für Nutzdaten belegt werden.\n</li></ul>"}], "trans": [{"from": "FIG-556e8594370c39dd", "to": "FIG-cbf1fedee81783b9", "fr": "R2.1.20", "tr": "R3.0.7", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-cbf1fedee81783b9", "to": "FIG-6f7a5d3a76c9c00d", "fr": "R3.0.7", "tr": "R3.1.5", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-6f7a5d3a76c9c00d", "to": "FIG-a2e193515cf12365", "fr": "R3.1.5", "tr": "R3.2.3", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li>Dokumenten- und Revisionskopf: Außerhalb des eigentlichen Diagrammrahmens oben rechts wurde die Versionsbeschriftung „V1.3.0 / R3.2 Rev 3“ hinzugefügt.\n</li></ul>"}]};
